mapper.select:
SELECT auth_group_id AS row_id, name AS auth_group_name, description, use_yn FROM auth_group WHERE use_yn = 'Y'
AND (auth_group_id LIKE '%' || #{filterKeyword} || '%' OR name LIKE '%' || #{filterKeyword} || '%')
ORDER BY auth_group_id LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE auth_group SET
    name = #{authGroupName}, description = #{description},
    upd_id = #{updId}, upd_dt = NOW(), upd_ip = #{updIp}
WHERE auth_group_id = #{rowId}
